# Standard library
import uuid

# Third-party
from sqlalchemy import func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithFactorMixin


class CoreRefAchievementType(Base, ReferenceWithFactorMixin):
    __tablename__ = "core_ref_achievement_type"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid(). Uniquely identifies an achievement type that "
            "describes the criteria mechanic (e.g. threshold, count, streak, "
            "collection)."
        ),
    )
